"""Durable storage for agent build plans.

Mirrors :mod:`rasa.builder.copilot.pydantic_ai.thread_store`: SQLite with WAL
mode plus conservative pragmas so this store's writers share the Copilot
history database file without tripping over v1/v2's own locks. Revisions are
insert-only — a plan is never overwritten, only appended to — so the full
edit history (planner runs and direct user edits alike) survives a restart.
"""

from __future__ import annotations

import asyncio
import os
import sqlite3
import uuid
from contextlib import contextmanager
from datetime import datetime, timezone
from typing import Generator

from rasa.builder.agent_plan.models import (
    AgentBuildPlan,
    AgentPlanRecord,
    PlanRevision,
    PlanStatus,
)

# Simple allowed-transition map: ``set_status`` refuses any move not listed
# here for the plan's current status. ``BUILT`` and ``DISCARDED`` have no
# outgoing edges — once there, a plan is done.
_ALLOWED_TRANSITIONS: dict[PlanStatus, set[PlanStatus]] = {
    PlanStatus.DRAFT: {PlanStatus.APPROVED, PlanStatus.DISCARDED},
    PlanStatus.APPROVED: {PlanStatus.BUILDING, PlanStatus.DISCARDED},
    PlanStatus.BUILDING: {PlanStatus.BUILT, PlanStatus.FAILED},
    PlanStatus.BUILT: set(),
    PlanStatus.FAILED: {PlanStatus.DRAFT, PlanStatus.DISCARDED},
    PlanStatus.DISCARDED: set(),
}


def _check_transition_allowed(current: PlanStatus, target: PlanStatus) -> None:
    if target not in _ALLOWED_TRANSITIONS[current]:
        raise InvalidPlanTransitionError(
            f"Cannot transition plan from {current.value!r} to {target.value!r}."
        )


class InvalidPlanTransitionError(ValueError):
    """Raised when a status transition isn't in the allowed-transitions map."""


class PlanNotFoundError(KeyError):
    """Raised when a plan id has no record in the store."""


class SQLitePlanStore:
    """SQLite-backed agent plan store.

    Two tables: ``agent_plans`` holds the mutable record (status, prompt,
    message history, job id), ``agent_plan_revisions`` is an insert-only log
    of every plan snapshot. All synchronous DB work runs via
    ``asyncio.to_thread``.
    """

    _PLANS_TABLE = "agent_plans"
    _REVISIONS_TABLE = "agent_plan_revisions"
    _BUSY_TIMEOUT_MS = 5000

    def __init__(self, db_path: str) -> None:
        if not db_path or not db_path.strip():
            raise ValueError(
                f"SQLitePlanStore requires a non-empty database path; got "
                f"{db_path!r}."
            )
        self._db_path = db_path
        db_dir = os.path.dirname(db_path)
        if db_dir:
            os.makedirs(db_dir, exist_ok=True)
        self._init_db()

    def _init_db(self) -> None:
        with self._connection() as conn:
            conn.execute(
                f"""
                CREATE TABLE IF NOT EXISTS {self._PLANS_TABLE} (
                    plan_id      TEXT PRIMARY KEY,
                    agent_id     TEXT NOT NULL DEFAULT '',
                    status       TEXT NOT NULL,
                    prompt       TEXT NOT NULL,
                    messages_json TEXT,
                    job_id       TEXT,
                    created_at   TEXT NOT NULL,
                    updated_at   TEXT NOT NULL
                )
                """
            )
            conn.execute(
                f"""
                CREATE TABLE IF NOT EXISTS {self._REVISIONS_TABLE} (
                    plan_id    TEXT NOT NULL,
                    revision   INTEGER NOT NULL,
                    source     TEXT NOT NULL,
                    plan_json  TEXT NOT NULL,
                    created_at TEXT NOT NULL,
                    PRIMARY KEY (plan_id, revision)
                )
                """
            )
            # Databases created before plans were scoped by agent.
            columns = {
                row[1]
                for row in conn.execute(f"PRAGMA table_info({self._PLANS_TABLE})")
            }
            if "agent_id" not in columns:
                conn.execute(
                    f"ALTER TABLE {self._PLANS_TABLE} "
                    f"ADD COLUMN agent_id TEXT NOT NULL DEFAULT ''"
                )
            conn.commit()

    @contextmanager
    def _connection(self) -> Generator[sqlite3.Connection, None, None]:
        conn = sqlite3.connect(self._db_path, timeout=self._BUSY_TIMEOUT_MS / 1000)
        try:
            conn.execute("PRAGMA journal_mode=WAL")
            conn.execute("PRAGMA synchronous=NORMAL")
            conn.execute(f"PRAGMA busy_timeout={self._BUSY_TIMEOUT_MS}")
            yield conn
        finally:
            conn.close()

    # ── synchronous helpers (run via asyncio.to_thread) ────────────────────

    def _create_plan(
        self, plan_id: str, agent_id: str, prompt: str, plan: AgentBuildPlan
    ) -> AgentPlanRecord:
        now = _now_iso()
        with self._connection() as conn:
            try:
                conn.execute(
                    f"""
                    INSERT INTO {self._PLANS_TABLE}
                        (plan_id, agent_id, status, prompt, messages_json,
                         job_id, created_at, updated_at)
                    VALUES (?, ?, ?, ?, NULL, NULL, ?, ?)
                    """,
                    (plan_id, agent_id, PlanStatus.DRAFT.value, prompt, now, now),
                )
                conn.execute(
                    f"""
                    INSERT INTO {self._REVISIONS_TABLE}
                        (plan_id, revision, source, plan_json, created_at)
                    VALUES (?, 1, 'planner', ?, ?)
                    """,
                    (plan_id, plan.model_dump_json(), now),
                )
                conn.commit()
            except Exception:
                conn.rollback()
                raise
        return _build_record(
            plan_id,
            agent_id,
            PlanStatus.DRAFT.value,
            prompt,
            None,
            now,
            now,
            1,
            "planner",
            plan,
        )

    def _get_plan(self, plan_id: str) -> AgentPlanRecord | None:
        with self._connection() as conn:
            plan_row = conn.execute(
                f"""
                SELECT agent_id, status, prompt, job_id, created_at, updated_at
                FROM {self._PLANS_TABLE} WHERE plan_id = ?
                """,
                (plan_id,),
            ).fetchone()
            if plan_row is None:
                return None
            revision_row = conn.execute(
                f"""
                SELECT revision, source, plan_json, created_at
                FROM {self._REVISIONS_TABLE}
                WHERE plan_id = ? ORDER BY revision DESC LIMIT 1
                """,
                (plan_id,),
            ).fetchone()
        if revision_row is None:
            return None
        agent_id, status, prompt, job_id, created_at, updated_at = plan_row
        revision, source, plan_json, revision_created_at = revision_row
        return _build_record(
            plan_id,
            agent_id,
            status,
            prompt,
            job_id,
            created_at,
            updated_at,
            revision,
            source,
            AgentBuildPlan.model_validate_json(plan_json),
            revision_created_at,
        )

    def _get_revision(self, plan_id: str, revision: int) -> PlanRevision | None:
        with self._connection() as conn:
            row = conn.execute(
                f"""
                SELECT revision, source, plan_json, created_at
                FROM {self._REVISIONS_TABLE}
                WHERE plan_id = ? AND revision = ?
                """,
                (plan_id, revision),
            ).fetchone()
        if row is None:
            return None
        revision_number, source, plan_json, created_at = row
        return PlanRevision(
            revision=revision_number,
            source=source,
            plan=AgentBuildPlan.model_validate_json(plan_json),
            created_at=datetime.fromisoformat(created_at),
        )

    def _list_plans(self, agent_id: str) -> list[AgentPlanRecord]:
        with self._connection() as conn:
            rows = conn.execute(
                f"""
                SELECT p.plan_id, p.status, p.prompt, p.job_id, p.created_at,
                       p.updated_at, r.revision, r.source, r.plan_json,
                       r.created_at
                FROM {self._PLANS_TABLE} p
                JOIN {self._REVISIONS_TABLE} r ON r.plan_id = p.plan_id
                WHERE p.agent_id = ?
                  AND p.status != ?
                  AND r.revision = (
                      SELECT MAX(revision) FROM {self._REVISIONS_TABLE}
                      WHERE plan_id = p.plan_id
                  )
                ORDER BY p.updated_at DESC
                """,
                (agent_id, PlanStatus.DISCARDED.value),
            ).fetchall()
        return [
            _build_record(
                plan_id,
                agent_id,
                status,
                prompt,
                job_id,
                created_at,
                updated_at,
                revision,
                source,
                AgentBuildPlan.model_validate_json(plan_json),
                revision_created_at,
            )
            for (
                plan_id,
                status,
                prompt,
                job_id,
                created_at,
                updated_at,
                revision,
                source,
                plan_json,
                revision_created_at,
            ) in rows
        ]

    def _add_revision(
        self, plan_id: str, plan: AgentBuildPlan, source: str
    ) -> AgentPlanRecord:
        now = _now_iso()
        with self._connection() as conn:
            # Claiming the write lock with this UPDATE before the MAX(revision)
            # read below is what makes the next-revision number race-free: a
            # concurrent add_revision blocks on this row until we commit or
            # roll back, instead of both readers computing the same number.
            cursor = conn.execute(
                f"UPDATE {self._PLANS_TABLE} SET updated_at = ? "
                f"WHERE plan_id = ? AND status = ?",
                (now, plan_id, PlanStatus.DRAFT.value),
            )
            if cursor.rowcount == 0:
                conn.rollback()
                exists = conn.execute(
                    f"SELECT 1 FROM {self._PLANS_TABLE} WHERE plan_id = ?",
                    (plan_id,),
                ).fetchone()
                if exists is None:
                    raise PlanNotFoundError(plan_id)
                raise InvalidPlanTransitionError(f"Plan {plan_id!r} is not a draft.")
            try:
                row = conn.execute(
                    f"SELECT MAX(revision) FROM {self._REVISIONS_TABLE} "
                    f"WHERE plan_id = ?",
                    (plan_id,),
                ).fetchone()
                if row is None or row[0] is None:
                    raise PlanNotFoundError(plan_id)
                next_revision = row[0] + 1
                conn.execute(
                    f"""
                    INSERT INTO {self._REVISIONS_TABLE}
                        (plan_id, revision, source, plan_json, created_at)
                    VALUES (?, ?, ?, ?, ?)
                    """,
                    (plan_id, next_revision, source, plan.model_dump_json(), now),
                )
                conn.commit()
            except Exception:
                conn.rollback()
                raise
        record = self._get_plan(plan_id)
        if record is None:
            raise PlanNotFoundError(plan_id)
        return record

    def _set_status(self, plan_id: str, status: PlanStatus) -> AgentPlanRecord:
        with self._connection() as conn:
            row = conn.execute(
                f"SELECT status FROM {self._PLANS_TABLE} WHERE plan_id = ?",
                (plan_id,),
            ).fetchone()
            if row is None:
                raise PlanNotFoundError(plan_id)
            current_status = PlanStatus(row[0])
            _check_transition_allowed(current_status, status)
            cursor = conn.execute(
                f"UPDATE {self._PLANS_TABLE} SET status = ?, updated_at = ? "
                f"WHERE plan_id = ? AND status = ?",
                (status.value, _now_iso(), plan_id, current_status.value),
            )
            if cursor.rowcount == 0:
                # Another writer moved the plan between the read and the write.
                conn.rollback()
                raise InvalidPlanTransitionError(
                    f"Plan {plan_id!r} changed status concurrently."
                )
            conn.commit()
        record = self._get_plan(plan_id)
        if record is None:
            raise PlanNotFoundError(plan_id)
        return record

    def _set_messages(self, plan_id: str, messages_json: bytes) -> None:
        with self._connection() as conn:
            cursor = conn.execute(
                f"UPDATE {self._PLANS_TABLE} SET messages_json = ? WHERE plan_id = ?",
                (messages_json.decode("utf-8"), plan_id),
            )
            if cursor.rowcount == 0:
                conn.rollback()
                raise PlanNotFoundError(plan_id)
            conn.commit()

    def _get_messages(self, plan_id: str) -> bytes | None:
        with self._connection() as conn:
            row = conn.execute(
                f"SELECT messages_json FROM {self._PLANS_TABLE} WHERE plan_id = ?",
                (plan_id,),
            ).fetchone()
        if row is None:
            raise PlanNotFoundError(plan_id)
        return row[0].encode("utf-8") if row[0] is not None else None

    # ── async API ────────────────────────────────────────────────────────

    async def create_plan(
        self, plan_id: str, agent_id: str, prompt: str, plan: AgentBuildPlan
    ) -> AgentPlanRecord:
        """Create a new plan, writing revision 1 with source ``"planner"``."""
        return await asyncio.to_thread(
            self._create_plan, plan_id, agent_id, prompt, plan
        )

    async def get_plan(self, plan_id: str) -> AgentPlanRecord | None:
        """Return the plan joined with its latest revision, or ``None``."""
        return await asyncio.to_thread(self._get_plan, plan_id)

    async def list_plans(self, agent_id: str) -> list[AgentPlanRecord]:
        """Return the agent's non-discarded plans, newest updated first."""
        return await asyncio.to_thread(self._list_plans, agent_id)

    async def get_revision(self, plan_id: str, revision: int) -> PlanRevision | None:
        """Return one specific revision of a plan, or ``None`` if missing."""
        return await asyncio.to_thread(self._get_revision, plan_id, revision)

    async def add_revision(
        self, plan_id: str, plan: AgentBuildPlan, source: str
    ) -> AgentPlanRecord:
        """Insert a new revision row and return the updated record.

        Raises:
            PlanNotFoundError: If no plan exists for ``plan_id``.
            InvalidPlanTransitionError: If the plan is not a draft. Only draft
                plans accept new revisions, since an approved or building plan
                is already pinned to a specific revision for its build.
        """
        return await asyncio.to_thread(self._add_revision, plan_id, plan, source)

    async def set_status(self, plan_id: str, status: PlanStatus) -> AgentPlanRecord:
        """Transition the plan's status per the allowed-transitions map."""
        return await asyncio.to_thread(self._set_status, plan_id, status)

    async def set_messages(self, plan_id: str, messages_json: bytes) -> None:
        """Store the serialized pydantic-ai message history for a plan."""
        await asyncio.to_thread(self._set_messages, plan_id, messages_json)

    async def get_messages(self, plan_id: str) -> bytes | None:
        """Return the stored serialized message history, or ``None``."""
        return await asyncio.to_thread(self._get_messages, plan_id)

    async def set_job_id(self, plan_id: str, job_id: str) -> AgentPlanRecord:
        """Attach the build job id to a plan and return the updated record."""
        return await asyncio.to_thread(self._set_job_id, plan_id, job_id)

    def _set_job_id(self, plan_id: str, job_id: str) -> AgentPlanRecord:
        now = _now_iso()
        with self._connection() as conn:
            cursor = conn.execute(
                f"UPDATE {self._PLANS_TABLE} SET job_id = ?, updated_at = ? "
                f"WHERE plan_id = ?",
                (job_id, now, plan_id),
            )
            if cursor.rowcount == 0:
                conn.rollback()
                raise PlanNotFoundError(plan_id)
            conn.commit()
        record = self._get_plan(plan_id)
        if record is None:
            raise PlanNotFoundError(plan_id)
        return record


def new_plan_id() -> str:
    """Return a fresh random plan id."""
    return uuid.uuid4().hex


def open_agent_plan_store() -> SQLitePlanStore:
    """Open the agent plan store against the shared Copilot history database.

    Local import keeps the config module (and its env-var reads) out of this
    module's import-time dependencies, mirroring
    ``thread_history.open_copilot_thread_store``.
    """
    from rasa.builder import config as builder_config

    return SQLitePlanStore(builder_config.COPILOT_HISTORY_SQLITE_PATH)


def _now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _build_record(
    plan_id: str,
    agent_id: str,
    status: str,
    prompt: str,
    job_id: str | None,
    created_at: str,
    updated_at: str,
    revision: int,
    source: str,
    plan: AgentBuildPlan,
    revision_created_at: str | None = None,
) -> AgentPlanRecord:
    return AgentPlanRecord(
        plan_id=plan_id,
        agent_id=agent_id,
        status=PlanStatus(status),
        prompt=prompt,
        latest_revision=PlanRevision(
            revision=revision,
            source=source,
            plan=plan,
            created_at=datetime.fromisoformat(revision_created_at or created_at),
        ),
        job_id=job_id,
        created_at=datetime.fromisoformat(created_at),
        updated_at=datetime.fromisoformat(updated_at),
    )
